'use strict';

const fs = require('node:fs'); const path = require('node:path');
const { immutableCopy } = require('../contracts/immutable'); const { assertProductSlug, getProductPath } = require('../state/product-state');
const IMAGE_PROVIDERS = Object.freeze({ gemini: { operation: 'image.generate', secret: 'GEMINI_API_KEY', model: 'gemini-3.1-flash-image' }, openrouter: { operation: 'image.generate', secret: 'OPENROUTER_API_KEY' }, freepik: { operation: 'image.generate', secret: 'FREEPIK_API_KEY' } });
function prepareImageRequest({ provider, prompt, secretProvider }) { const definition = IMAGE_PROVIDERS[provider]; if (!definition) throw new Error('image provider is not allowlisted'); if (!prompt || typeof prompt !== 'string') throw new TypeError('image prompt is required'); if (!secretProvider || !secretProvider.has_secret(definition.secret)) return immutableCopy({ provider, status: 'error', error: 'secret_unavailable', required_secret: definition.secret, external_executable: false }); const injection = secretProvider.run_with_secrets({ id: definition.operation, allowed_secret_names: [definition.secret] }, [definition.secret]); return immutableCopy({ provider, status: 'dry_run', operation: definition.operation, required_secret: definition.secret, injection, external_executable: false }); }
function writeMockImageArtifact({ projectRoot, product_slug, provider, request_id = null, status = 'success' }) { const slug = assertProductSlug(product_slug); const output = path.join(getProductPath(slug, projectRoot), 'entregas', 'criativos', `image-${provider}-mock.png`); if (status !== 'success') return immutableCopy({ provider, status: 'error', artifact_path: null, mime_type: null, width: null, height: null, request_id, error: 'provider_error' }); fs.mkdirSync(path.dirname(output), { recursive: true }); fs.writeFileSync(output, 'mock-image'); return immutableCopy({ provider, status: 'success', artifact_path: output, mime_type: 'image/png', width: 1, height: 1, request_id, error: null }); }
module.exports = { IMAGE_PROVIDERS, prepareImageRequest, writeMockImageArtifact };
